#   python3 tools/i18n_2026_11_07_eng33.py texts   rewrite bramblewood-texts.js (Poison counters -> Venom, the changed values, the new keys) and
#                                                  rename / add the rows in lang/<code>.json (keyed by English text, order kept, new rows at the end)
#   python3 tools/i18n_2026_11_07_eng33.py ui      rename the lang/ui/<code>.json rows whose English text in arena_app.js changed (Poison -> Venom)
# Translations: the counters' word is unchanged in every language but French (Poison -> Venin, empoisonné -> envenimé): German Gift, Spanish
# and Portuguese veneno, Italian veleno, Indonesian racun, Tagalog lason, Tamil நஞ்சு, Chinese / Japanese 毒, Korean 독 already cover venom.
# The skill's new name (Venomous) and the new texts are translated in full below.
# Run once on 2026-11-07. Afterwards (tests/d-2026-10-19: a short description stays under 20 words) by hand: ui.eng9-undead went back to its
# old text (the undead status shows in the Codex's undead-rule chip instead), ui.eng33-thanatosis became "First time at 0 Health: it plays dead
# instead of dying, then gets up next round with 1 Health." and its Codex note starts "Once a fight." (all 12 packs, same wording).
import json, re, sys
CODES = ['fr', 'de', 'es', 'it', 'pt', 'tl', 'ta', 'id', 'zh-Hans', 'zh-Hant', 'ja', 'ko']
KEEP = ['Poison Barbs', 'Poison Bolt', 'poison bolt', 'Poison Gas', 'poison gas', 'Poison Floor', 'Poison Dart', 'Deadly Poison', 'Greater Poison', 'Poison-dart', 'poison-dart']
def venomize(s):
    ph = {}
    def prot(m):
        k = '\x00%d\x00' % len(ph); ph[k] = m.group(0); return k
    for w in KEEP: s = re.sub(re.escape(w), prot, s)
    for a, b in [(r'\bPoison-proof', 'Venom-proof'), (r'\bpoison-proof', 'venom-proof'), (r'\bmost poisoned\b', 'most envenomed'), (r'\ba Poisoned\b', 'an Envenomed'),
                 (r'\bPoisoned\b', 'Envenomed'), (r'\bpoisoned\b', 'envenomed'), (r'\bPoisons\b', 'Envenoms'), (r'\bpoisons\b', 'envenoms'),
                 (r'\bPoison\b', 'Venom'), (r'\bpoison\b', 'venom')]:
        s = re.sub(a, b, s)
    for k, v in ph.items(): s = s.replace(k, v)
    return s
def fr_venom(s):
    for a, b in [(r'\bempoisonnée', 'envenimée'), (r'\bempoisonné', 'envenimé'), (r'\bEmpoisonnée', 'Envenimée'), (r'\bEmpoisonné', 'Envenimé'), (r'\bempoisonner', 'envenimer'),
                 (r'\bempoisonne\b', 'envenime'), (r'\bPoison\b', 'Venin'), (r'\bpoison\b', 'venin')]:
        s = re.sub(a, b, s)
    return s
def carry(code, old_tr): return fr_venom(old_tr) if code == 'fr' else old_tr

